script:
const phanHe = ctx.val('phan_he', 'maintenance').trim().toLowerCase() || 'maintenance';
const targetUrl = `https://tasks.zuizui.io/${phanHe}/create/list`;

await step('Mở panel Bộ lọc nâng cao', async () => {
  if (!page.url().includes(`/${phanHe}/`)) {
    await page.goto(targetUrl, { waitUntil: 'domcontentloaded' });
  }
  await page.waitForLoadState('networkidle', { timeout: 25000 }).catch(() => {});
  const filterBtn = page.locator('.ltv-filter-bar__pagination__btn.ltv-filter-bar__filter-btn, .ltv-filter-bar__filter-btn').first();
  await filterBtn.waitFor({ timeout: 15000 });
  await filterBtn.click();
  await page.getByText('Bộ lọc', { exact: true }).first().waitFor({ timeout: 10000 });
});

await step('Chọn tiêu chí lọc (Phân loại, Vùng miền, SLA, Độ ưu tiên, Loại phiếu)', async () => {
  // Phân loại phiếu
  const firstInput = page.locator('.MuiInputBase-root').first();
  await firstInput.click();
  await pickOption(page.getByRole('option'), 'phan_loai');

  // Vùng miền -> Chọn tất cả nếu có
  const regionInput = page.getByRole('textbox', { name: 'Vùng miền' });
  if (await regionInput.isVisible().catch(() => false)) {
    await regionInput.click();
    const selectAll = page.getByRole('option', { name: 'Chọn tất cả' }).first();
    if (await selectAll.isVisible().catch(() => false)) await selectAll.click();
    await page.keyboard.press('Escape').catch(() => {});
  }

  // SLA hoàn tất
  const slaDoneInput = page.getByRole('textbox', { name: 'SLA hoàn tất' });
  if (await slaDoneInput.isVisible().catch(() => false)) {
    await slaDoneInput.click();
    await pickOption(page.getByRole('option'), 'sla_hoan_tat');
  }

  // Loại phiếu
  const typeInput = page.getByRole('textbox', { name: 'Loại phiếu', exact: true });
  if (await typeInput.isVisible().catch(() => false)) {
    await typeInput.click();
    await pickOption(page.getByRole('option'), 'loai_phieu');
  }

  // Độ ưu tiên
  const prioInput = page.getByRole('textbox', { name: 'Độ ưu tiên' });
  if (await prioInput.isVisible().catch(() => false)) {
    await prioInput.click();
    await pickOption(page.getByRole('option'), 'do_uu_tien');
  }
});

await step('Kiểm tra các trường lọc còn lại hiện diện', async () => {
  for (const label of ['Người phụ trách', 'Người hỗ trợ', 'Người tạo', 'Điểm đánh giá', 'SLA tiếp nhận', 'Tổng thời gian thực hiện']) {
    const visible = await page.getByRole('textbox', { name: label }).isVisible().catch(() => false);
    if (!visible) ctx.log('Lưu ý: không thấy ô ' + label);
  }
});

await step('Bấm Áp dụng và kiểm tra dialog Lưu bộ lọc', async () => {
  await page.locator('div').filter({ hasText: /^Áp dụng$/ }).first().click();
  await page.waitForLoadState('networkidle', { timeout: 15000 }).catch(() => {});

  const saveFilterBtn = page.getByText('Lưu bộ lọc').first();
  if (await saveFilterBtn.isVisible().catch(() => false)) {
    await saveFilterBtn.click();
    const nameInput = page.getByRole('textbox', { name: 'Tên bộ lọc *' });
    await nameInput.waitFor({ timeout: 8000 });
    await nameInput.fill(ctx.val('ten_bo_loc', 'Lưu bộ lọc'));
    await page.keyboard.press('Escape').catch(() => {});
  }
  ctx.log('Đã kiểm tra bộ lọc nâng cao và dialog Lưu bộ lọc thành công.');
});
